  timeline: common.TimelineEvent[];
  draftSavedAt: string;
  submittedAt?: string | null;
  decisionTargetAt?: string | null;
  /** Only when state = approved: account status, product approval, payout readiness and the finish-setup checklist, from the same sources as GET /api/seller/sellers/setup, so sell/status can show them on the customer session */
