  errorCodes: {
    "APPLICATION_EXISTS": {
      "status": 409,
      "meaning": "This account already has an open application"
    },
    "APPLICATION_INCOMPLETE": {
      "status": 400,
      "meaning": "Steps are missing information; details.missing lists fields per step"
    },
    "AGREEMENT_VERSION_OUTDATED": {
      "status": 409,
      "meaning": "A newer agreement version is now effective; reload and accept it"
    },
    "REAPPLY_NOT_YET": {
      "status": 409,
      "meaning": "A previous rejection set a reapply date; details.canReapplyFrom"
    },
    "INVITATION_REQUIRED": {
      "status": 403,
      "meaning": "Applications are invite-only right now"
    },
    "CHECKS_UNRESOLVED": {
      "status": 409,
      "meaning": "Verification checks are failed or need attention without an accepted note; details.checks"
    },
    "APPEAL_WINDOW_CLOSED": {
      "status": 409,
      "meaning": "The appeal deadline has passed"
    },
    "APPEAL_ALREADY_OPEN": {
      "status": 409,
      "meaning": "An appeal for this decision and level is already open"
    },
    "SAME_REVIEWER_NOT_ALLOWED": {
      "status": 409,
      "meaning": "The reviewer or second reviewer made the original decision or the request"
    },
    "NOT_DELEGABLE": {
      "status": 422,
      "meaning": "This permission can never be given to staff (payout changes) or is owner-only"
    },
    "MEMBER_EXISTS": {
      "status": 409,
      "meaning": "This email is already a member or invited"
    },
    "LAST_OWNER": {
      "status": 409,
      "meaning": "The owner cannot be removed or suspended"
    },
    "PAYOUT_DETAILS_INVALID": {
      "status": 422,
      "meaning": "Routing number invalid, numbers do not match or the provider refused the account"
    },
    "STORE_NAME_TAKEN": {
      "status": 409,
      "meaning": "Another seller uses this store name"
    },
    "COLLECTION_LIMIT_REACHED": {
      "status": 409,
      "meaning": "maxCollections already exist"
    },
    "SELLER_HAS_OPEN_OBLIGATIONS": {
      "status": 409,
      "meaning": "Orders, returns, cases or money are still open; details.obligations lists them"
    },
    "LAUNCH_REVIEW_NOT_READY": {
      "status": 409,
      "meaning": "Payout verification and a first submission are needed first; details.missing"
    }
  },
